//! `cargo xtask emoji-data <version>`: `EmojiPicker`'s emoji
//! (`crates/nsh-base/src/emoji_picker/emoji.tsv`) from a release of
//! emojibase-data, whose English names and keywords come from CLDR.
//!
//! One line per emoji in emojibase's order, its fields apart by tabs: the
//! emoji (fully qualified), its group (emojibase's number), the Emoji
//! version that added it, its light skin tone's form for one tone on
//! every person (empty when it takes none), its name, then its keywords.
//! The skin tone's forms are checked here: the other four tones are the
//! light one's with its modifier swapped, for every emoji, so the picker
//! never builds a sequence by rules of its own.

use std::{collections::BTreeSet, fmt::Write as _, fs, path::Path, process::Command};

use anyhow::{Context, bail, ensure};
use serde_json::Value;

use crate::{android, term};

/// emojibase's groups by number: what the picker's `EmojiGroupId`s are.
/// The skin tone modifiers' group (`component`) is left out.
const GROUPS: [&str; 10] = [
    "smileys-emotion",
    "people-body",
    "component",
    "animals-nature",
    "food-drink",
    "travel-places",
    "activities",
    "objects",
    "symbols",
    "flags",
];

/// The group left out.
const COMPONENT: u64 = 2;

/// The skin tone modifiers, light to dark (U+1F3FB..=U+1F3FF).
const TONES: [char; 5] = [
    '\u{1F3FB}',
    '\u{1F3FC}',
    '\u{1F3FD}',
    '\u{1F3FE}',
    '\u{1F3FF}',
];

/// Where the data goes.
const OUT: &str = "crates/nsh-base/src/emoji_picker/emoji.tsv";

pub(crate) fn generate(version: &str) -> anyhow::Result<()> {
    let step = term::Step::start(format!("emojibase-data@{version}"));
    let data = fetch(version, "en/data.json")?;
    let messages = fetch(version, "en/messages.json")?;
    check_groups(&messages)?;
    let text = tsv(version, &data)?;
    let out = android::root().join(OUT);
    fs::write(&out, &text).with_context(|| format!("write {}", out.display()))?;
    step.done(format!(
        "{} emoji, {} KB in {}",
        text.lines().filter(|l| !l.starts_with('#')).count(),
        text.len() / 1000,
        Path::new(OUT).display()
    ));
    Ok(())
}

/// A file of the release from jsDelivr's copy of the npm package.
fn fetch(version: &str, file: &str) -> anyhow::Result<Value> {
    let url = format!("https://cdn.jsdelivr.net/npm/emojibase-data@{version}/{file}");
    let output = Command::new("curl")
        .args(["-fsSL", &url])
        .output()
        .context("run curl")?;
    ensure!(
        output.status.success(),
        "download {url}: {}",
        String::from_utf8_lossy(&output.stderr).trim()
    );
    serde_json::from_slice(&output.stdout).with_context(|| format!("parse {url}"))
}

/// The release numbers its groups as [`GROUPS`] does.
fn check_groups(messages: &Value) -> anyhow::Result<()> {
    let groups = messages["groups"]
        .as_array()
        .context("messages.json has no groups")?;
    for group in groups {
        let (Some(key), Some(order)) = (group["key"].as_str(), group["order"].as_u64()) else {
            bail!("a group of messages.json has no key or order: {group}");
        };
        ensure!(
            GROUPS.get(order as usize) == Some(&key),
            "emojibase's group {order} is `{key}`, not `{}`",
            GROUPS.get(order as usize).unwrap_or(&"")
        );
    }
    Ok(())
}

fn tsv(version: &str, data: &Value) -> anyhow::Result<String> {
    let mut entries: Vec<&Value> = data
        .as_array()
        .context("data.json is no array")?
        .iter()
        .filter(|e| e["group"].as_u64().is_some_and(|g| g != COMPONENT))
        .collect();
    entries.sort_by_key(|e| e["order"].as_u64().unwrap_or(u64::MAX));
    let mut out = format!(
        "# Generated by `cargo xtask emoji-data {version}` from emojibase-data@{version} \
         (MIT; names and keywords from Unicode CLDR, Unicode License v3: emoji.LICENSE.txt).\n\
         # emoji\tgroup\tversion\tlight skin tone\tname\tkeywords...\n"
    );
    let mut seen = BTreeSet::new();
    for entry in entries {
        let emoji = field(entry, "emoji")?;
        ensure!(seen.insert(emoji), "`{emoji}` twice");
        let label = field(entry, "label")?;
        let group = entry["group"].as_u64().unwrap_or_default();
        let added = match &entry["version"] {
            Value::Number(n) => n.to_string(),
            other => bail!("`{emoji}` has the version {other}"),
        };
        let tone = skin_tone(emoji, entry)?;
        let folded = label.to_lowercase();
        // A keyword the name holds matches nothing more.
        let keywords: Vec<&str> = entry["tags"]
            .as_array()
            .map(|tags| tags.iter().filter_map(Value::as_str).collect::<Vec<_>>())
            .unwrap_or_default()
            .into_iter()
            .filter(|tag| !folded.contains(&tag.to_lowercase()))
            .collect();
        for text in [emoji, label, &tone]
            .into_iter()
            .chain(keywords.iter().copied())
        {
            ensure!(
                !text.contains(['\t', '\n']),
                "`{emoji}`: a tab or line break in `{text}`"
            );
        }
        write!(out, "{emoji}\t{group}\t{added}\t{tone}\t{label}")?;
        for keyword in keywords {
            write!(out, "\t{keyword}")?;
        }
        out.push('\n');
    }
    Ok(out)
}

fn field<'a>(entry: &'a Value, name: &str) -> anyhow::Result<&'a str> {
    entry[name]
        .as_str()
        .with_context(|| format!("an emoji has no {name}: {entry}"))
}

/// The light skin tone's form of `emoji` on every person, after checking
/// that each other tone's is it with the modifier swapped; empty when it
/// takes no skin tone.
fn skin_tone(emoji: &str, entry: &Value) -> anyhow::Result<String> {
    let Some(skins) = entry["skins"].as_array() else {
        return Ok(String::new());
    };
    let mut uniform: [Option<&str>; 5] = [None; 5];
    for skin in skins {
        let tones: Vec<u64> = match &skin["tone"] {
            Value::Number(n) => n.as_u64().into_iter().collect(),
            Value::Array(tones) => tones.iter().filter_map(Value::as_u64).collect(),
            other => bail!("`{emoji}` has a skin of tone {other}"),
        };
        let first = tones.first().copied().unwrap_or_default();
        if (1..=5).contains(&first) && tones.iter().all(|&t| t == first) {
            uniform[first as usize - 1] = Some(field(skin, "emoji")?);
        }
    }
    let Some(light) = uniform[0] else {
        bail!("`{emoji}` takes skin tones but has no light one");
    };
    ensure!(
        light.contains(TONES[0]),
        "`{emoji}`'s light skin tone `{light}` has no modifier"
    );
    for (tone, form) in TONES.iter().zip(uniform) {
        let built = light.replace(TONES[0], &tone.to_string());
        ensure!(
            form == Some(built.as_str()),
            "`{emoji}`'s skin tone {tone:?}: emojibase has {form:?}, the light one's swapped is `{built}`"
        );
    }
    Ok(light.to_owned())
}
